const CFG = $('CONFIG').first().json;
const canal = String(CFG.discordCoordId || '').trim();
if (!/^\d{5,}$/.test(canal)) {
  console.log('[wf12] discordCoordId sin configurar: no se manda nada');
  return [];
}

const ventana = Number(CFG.ventanaDias || 7);
const estados = String(CFG.estadosChequeados || 'activo,entregando')
  .split(',').map(s => s.trim()).filter(Boolean);
const avisarSiOk = String(CFG.avisarSiTodoAlDia || 'true') !== 'false';

const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
const corte = new Date(hoy); corte.setDate(corte.getDate() - ventana);

const parse = (s) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s || '').trim());
  return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
};
const dmy = (d) => String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0');
const diasDesde = (d) => Math.round((hoy - d) / 86400000);

const proyectos = $('Leer Projects').all().map(i => i.json).filter(r => r && r.id);
const cal = $('Leer Calendar').all().map(i => i.json).filter(r => r && r.project_id);

const atrasados = [], alDia = [], sinEmpezar = [];

for (const p of proyectos) {
  if (!estados.includes(String(p.status || '').trim())) continue;

  /* ¿Ya arrancó? Pedir jornadas de algo que empieza el mes que viene es ruido. */
  const inicios = [];
  let td = {};
  try { td = JSON.parse(p.taskDates_json || '{}') || {}; } catch (e) { td = {}; }
  /* mismo criterio que wf11: se miran todos los rangos, no solo el primero */
  Object.values(td).forEach(d => {
    if (!d) return;
    const tramos = [{ inicio: d.inicio, fin: d.fin }].concat(Array.isArray(d.rangos) ? d.rangos : []);
    tramos.forEach(r => { const f = parse(r && (r.inicio || r.fin)); if (f) inicios.push(f); });
  });
  cal.filter(r => String(r.project_id) === String(p.id))
     .forEach(r => { const f = parse(r.inicio || r.fin); if (f) inicios.push(f); });
  const arranque = inicios.length ? new Date(Math.min(...inicios.map(d => d.getTime()))) : null;
  if (arranque && arranque > hoy) { sinEmpezar.push(p.nombre || p.id); continue; }

  /* El tracker no guarda fecha de modificación, así que la señal de "actualizado"
     es la jornada más reciente marcada, mirando a todos los participantes. */
  let tr = {};
  try { tr = JSON.parse(p.tracker_json || '{}') || {}; } catch (e) { tr = {}; }
  const marcas = [];
  Object.values(tr.jornadas || {}).forEach(dias => {
    Object.keys(dias || {}).forEach(k => { if (dias[k]) { const f = parse(k); if (f) marcas.push(f); } });
  });

  if (!marcas.length) {
    atrasados.push({ nombre: p.nombre || p.id, detalle: 'sin ninguna jornada cargada' });
    continue;
  }
  const ultima = new Date(Math.max(...marcas.map(d => d.getTime())));
  if (ultima < corte) {
    const n = diasDesde(ultima);
    atrasados.push({ nombre: p.nombre || p.id, detalle: '\u00faltima jornada ' + dmy(ultima) + ' (hace ' + n + ' d\u00eda' + (n === 1 ? '' : 's') + ')' });
  } else {
    alDia.push(p.nombre || p.id);
  }
}

console.log('[wf12] atrasados ' + atrasados.length + ' \u00b7 al d\u00eda ' + alDia.length + ' \u00b7 sin empezar ' + sinEmpezar.length);
if (!atrasados.length && !avisarSiOk) return [];

const lineas = ['\ud83d\uddd3\ufe0f **Recordatorio: actualizar el tracker de jornadas**'];
if (atrasados.length) {
  lineas.push('', 'Sin cargas en los \u00faltimos ' + ventana + ' d\u00edas:');
  atrasados.slice(0, 20).forEach(a => lineas.push('\u2022 **' + a.nombre + '** \u00b7 ' + a.detalle));
  if (atrasados.length > 20) lineas.push('\u2026y ' + (atrasados.length - 20) + ' m\u00e1s');
  if (alDia.length) lineas.push('', 'Al d\u00eda: ' + alDia.length + ' proyecto' + (alDia.length === 1 ? '' : 's') + '.');
} else {
  lineas.push('', 'Todos los proyectos en curso est\u00e1n al d\u00eda.');
}
return [{ json: { channelId: canal, content: lineas.join('\n').slice(0, 1900) } }];
